import { Button } from "@qingye/ui/components/button";
import { Field, FieldLabel, FieldError } from "@qingye/ui/components/field";
import { Input } from "@qingye/ui/components/input";

/** Project composition. The application owns the draft and save result. */
export function ResourceEditor({ title, onTitleChange, onSave, saving = false, error }: { title: string; onTitleChange: (value: string) => void; onSave: () => void; saving?: boolean; error?: string }) {
  return <form onSubmit={(event) => { event.preventDefault(); onSave(); }}><Field><FieldLabel>Resource name</FieldLabel><Input value={title} onValueChange={onTitleChange} aria-invalid={Boolean(error)} />{error && <FieldError>{error}</FieldError>}</Field><Button type="submit" state={saving ? "in-progress" : "idle"}>Save draft</Button></form>;
}
